import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Bento Grids — Advanced & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"bento-grids-03-advanced-and-customization.md","filePath":"bento-grids-03-advanced-and-customization.md"}'),r={name:"bento-grids-03-advanced-and-customization.md"};function n(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="bento-grids-—-advanced-customization" tabindex="-1">Bento Grids — Advanced &amp; Customization <a class="header-anchor" href="#bento-grids-—-advanced-customization" aria-label="Permalink to &quot;Bento Grids — Advanced &amp; Customization&quot;">​</a></h1><p><em>Getting the most from Bento Grids across different audiences and use cases</em></p><hr><h2 id="choosing-the-right-aspect-ratio" tabindex="-1">Choosing the Right Aspect Ratio <a class="header-anchor" href="#choosing-the-right-aspect-ratio" aria-label="Permalink to &quot;Choosing the Right Aspect Ratio&quot;">​</a></h2><p>The aspect ratio shapes how the grid looks and where it can be used most effectively.</p><table tabindex="0"><thead><tr><th>Ratio</th><th>Best for</th></tr></thead><tbody><tr><td><strong>16:9</strong></td><td>Slides — fits standard presentation dimensions; works in PowerPoint and Google Slides</td></tr><tr><td><strong>4:3</strong></td><td>Documents and reports — fits older presentation formats and printed pages</td></tr><tr><td><strong>1:1</strong></td><td>Social media — square format for LinkedIn, Twitter, or internal wikis</td></tr></tbody></table><p>For most situations where the grid will be shared in a presentation or stakeholder meeting, 16:9 is the right choice.</p><hr><h2 id="single-image-vs-presentation-mode" tabindex="-1">Single Image vs Presentation Mode <a class="header-anchor" href="#single-image-vs-presentation-mode" aria-label="Permalink to &quot;Single Image vs Presentation Mode&quot;">​</a></h2><p>This setting controls whether the export contains one image or multiple slides.</p><p><strong>Single image</strong> is better when:</p><ul><li>You want a quick visual summary to drop into a Slack message, email, or document</li><li>The audience will see everything at once without narration</li></ul><p><strong>Presentation mode</strong> is better when:</p><ul><li>You&#39;ll be walking through the release in a meeting</li><li>Each feature deserves its own moment — one slide per cell lets you pace the conversation</li><li>You want to add speaker notes or context to individual items in PowerPoint or Google Slides</li></ul><hr><h2 id="getting-better-ai-grouping" tabindex="-1">Getting Better AI Grouping <a class="header-anchor" href="#getting-better-ai-grouping" aria-label="Permalink to &quot;Getting Better AI Grouping&quot;">​</a></h2><p>The AI groups your release content into cells by identifying distinct topics and themes. The quality of the grouping depends on how the source content is structured.</p><p><strong>If you&#39;re generating from Release Notes</strong>, write your notes with distinct headings or feature blocks. Notes that run together as a single paragraph are harder to parse into meaningful cells.</p><p><strong>If you&#39;re uploading a file</strong>, use a structured format — markdown with clear headings works best. Avoid content that mixes multiple features in one paragraph.</p><p>The review step exists precisely because the AI isn&#39;t always right. Use it to:</p><ul><li>Split a cell that has too many ideas</li><li>Merge cells that cover the same topic</li><li>Reorder cells to tell a better story</li></ul><hr><h2 id="using-bento-grids-for-different-audiences" tabindex="-1">Using Bento Grids for Different Audiences <a class="header-anchor" href="#using-bento-grids-for-different-audiences" aria-label="Permalink to &quot;Using Bento Grids for Different Audiences&quot;">​</a></h2><h3 id="customer-facing-teams-sales-cs-marketing" tabindex="-1">Customer-facing teams (Sales, CS, Marketing) <a class="header-anchor" href="#customer-facing-teams-sales-cs-marketing" aria-label="Permalink to &quot;Customer-facing teams (Sales, CS, Marketing)&quot;">​</a></h3><p>Use a light theme, enable icons, and choose Presentation mode. Walk through what shipped and what it means for customers. The visual format is more digestible than a text-based release note and easier to reference in a customer conversation.</p><h3 id="leadership-and-executives" tabindex="-1">Leadership and executives <a class="header-anchor" href="#leadership-and-executives" aria-label="Permalink to &quot;Leadership and executives&quot;">​</a></h3><p>Use Single Image mode. One concise slide that shows the release at a glance — no scrolling or narration required. Ideal for a weekly or monthly status summary.</p><h3 id="internal-retrospectives" tabindex="-1">Internal retrospectives <a class="header-anchor" href="#internal-retrospectives" aria-label="Permalink to &quot;Internal retrospectives&quot;">​</a></h3><p>Use Presentation mode in dark theme. Work through each cell in your retrospective meeting, using each slide as a conversation starter.</p><hr><h2 id="integrating-bento-grids-with-your-release-workflow" tabindex="-1">Integrating Bento Grids with Your Release Workflow <a class="header-anchor" href="#integrating-bento-grids-with-your-release-workflow" aria-label="Permalink to &quot;Integrating Bento Grids with Your Release Workflow&quot;">​</a></h2><p>The most effective pattern is to build Bento Grids as the last step of your release process:</p><ol><li>Complete the Release in Lodestone</li><li>Generate Release Notes (internal audience first)</li><li>Create a Bento Grid from those Release Notes</li><li>Export and share with the relevant audience</li></ol><p>This makes the Bento Grid a natural by-product of your existing workflow rather than a separate effort.</p><hr><h2 id="using-google-slides-for-collaborative-editing" tabindex="-1">Using Google Slides for Collaborative Editing <a class="header-anchor" href="#using-google-slides-for-collaborative-editing" aria-label="Permalink to &quot;Using Google Slides for Collaborative Editing&quot;">​</a></h2><p>The Google Slides export is useful when you want to edit the grid after export — for example, to add customer logos, callout notes, or additional slides.</p><p>Upload the grid to Google Slides and then edit it directly in Google. This works best when the Bento Grid is your starting point, and you want to add context or customization on top.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — common questions, edge cases, and what to do when things don&#39;t behave as expected.</em></p>',40)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
